from pathlib import Path
import base64
import html
import json

ROOT = Path(__file__).parent
ASSETS = ROOT / 'assets'
pages = []
NAVY, BLUE, CYAN = '#00255A', '#0069C8', '#50C0E8'

def data_uri(path):
    mime = 'font/woff2' if path.suffix == '.woff2' else 'image/png'
    return 'data:' + mime + ';base64,' + base64.b64encode(path.read_bytes()).decode()

def logo(width=220, variant='primary', symbol=False):
    # Reference reconstruction; production status documented on pages 2, 8 and 31.
    ink = '#FFFFFF' if variant == 'reverse' else ('#000000' if variant == 'black' else NAVY)
    mono = variant in ('white', 'black', 'navy')
    if variant == 'white': ink = '#FFFFFF'
    fill1 = ink if mono else BLUE
    fill2 = ink if mono else '#008EE8'
    fill3 = ink if mono else NAVY
    mark = f'''<path d="M4 27H23L60 93L50 105Z" fill="{fill1}"/>
      <path d="M60 93L47 69L65 40H86Z" fill="{fill2}"/>
      <path d="M23 27L60 93L50 105L35 79Z" fill="{fill3}" opacity=".38"/>
      <g fill="{fill2}"><path d="M77 29h7v7h-7zM82 19h6v6h-6zM91 15h5v5h-5zM89 6h5v5h-5zM98 1h4v4h-4zM96 25h4v4h-4z"/></g>'''
    text = '' if symbol else f'<text x="116" y="85" fill="{ink}" font-family="Inter,Arial,sans-serif" font-size="64" font-weight="750" letter-spacing="-3">VSPH</text>'
    return f'<svg class="brand-logo" width="{width}" viewBox="0 0 {108 if symbol else 299} 110" role="img" aria-label="VSPH">{mark}{text}</svg>'

def icon(name, size=40):
    paths = {
      'web':'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c6 5 6 13 0 18M12 3c-6 5-6 13 0 18M5 7h14M5 17h14"/>',
      'mobile':'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 5h4M11 19h2"/>',
      'layers':'<path d="m12 3 10 5-10 5L2 8Zm-10 10 10 5 10-5M2 18l10 5 10-5"/>',
      'people':'<circle cx="9" cy="7" r="3"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 4a3 3 0 0 1 0 6M20 21v-3a7 7 0 0 0-3-5"/>',
      'shield':'<path d="m12 2 9 4v6c0 5-5 8-9 10-4-2-9-5-9-10V6Zm-4 9 3 3 5-6"/>',
      'scale':'<path d="M4 21v-5M9 21V11M14 21V6M19 21V2"/>',
      'idea':'<path d="M8 18h8M9 22h6M8 15c0-3-3-3-3-7a7 7 0 0 1 14 0c0 4-3 4-3 7"/>',
      'support':'<path d="M3 13v-2a9 9 0 0 1 18 0v2M3 12H1v7h4v-7Zm18 0h2v7h-4v-7ZM21 19c0 3-4 3-7 3"/>'
    }
    return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths[name]}</svg>'

def motif(color=CYAN, opacity=.45):
    lines = ''.join(f'<path d="M{25+i*28} 680L{300+i*18} 330L{510+i*14} 430L{880+i*15} 0"/>' for i in range(12))
    squares = ''.join(f'<rect x="{650+i*25}" y="{155-i*23}" width="{7+i%3*3}" height="{7+i%3*3}" fill="{color}" stroke="none"/>' for i in range(8))
    return f'<svg class="motif" data-overflow-ignore="true" viewBox="0 0 1122 794" fill="none" stroke="{color}" stroke-width="1" opacity="{opacity}" aria-hidden="true">{lines}{squares}</svg>'

def page(section, title, body, cls='', kicker=None):
    n = len(pages) + 1
    header = f'<header><span>VSPH / BRAND GUIDELINES</span><span>{section}</span></header>'
    footer = f'<footer><span>PEOPLE &nbsp; / &nbsp; PRODUCTS &nbsp; / &nbsp; POSSIBILITIES</span><span>VERSION 1.0 &nbsp; · &nbsp; SEPTEMBER 2026</span><b>{n:02}</b></footer>'
    heading = f'<div class="title"><div class="eyebrow">{kicker or section}</div><h1>{title}</h1></div>' if title else ''
    pages.append(f'<section class="page {cls}" data-document-role="page" data-label="{html.escape(title or section)}" id="page-{n}">{header}{heading}<main>{body}</main>{footer}</section>')

def divider(num, title, desc, tags):
    page(title.upper(), '', f'{motif()}<div class="divider-copy"><div class="chapter">{num}</div><h1>{title}</h1><p>{desc}</p><div class="divider-tags">{tags}</div></div>', 'divider dark')

def info(title, text, num=''):
    return f'<div class="info"><div class="eyebrow">{num}</div><h3>{title}</h3><p>{text}</p></div>'

